export async function listTools() {
  return [
    {
      name: 'calculate',
      description: 'Perform a basic arithmetic operation on two numbers',
      inputSchema: {
        type: 'object',
        properties: {
          a: { type: 'number', description: 'First operand' },
          b: { type: 'number', description: 'Second operand' },
          operation: {
            type: 'string',
            enum: ['add', 'subtract', 'multiply', 'divide'],
            description: 'Arithmetic operation to perform'
          }
        },
        required: ['a', 'b', 'operation'],
        additionalProperties: false
      }
    }
  ];
}

const ALLOWED_KEYS = new Set(['a', 'b', 'operation']);
const OPERATIONS = {
  add: (a, b) => a + b,
  subtract: (a, b) => a - b,
  multiply: (a, b) => a * b,
  divide: (a, b) => a / b
};

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const input = args && typeof args === 'object' ? args : {};

  // Reject extra/unknown fields.
  for (const key of Object.keys(input)) {
    if (!ALLOWED_KEYS.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  // Reject missing required fields.
  for (const key of ALLOWED_KEYS) {
    if (!Object.prototype.hasOwnProperty.call(input, key)) {
      throw new Error(`Missing required field: ${key}`);
    }
  }

  const { a, b, operation } = input;

  // Validate numeric operands.
  if (typeof a !== 'number' || typeof b !== 'number' || Number.isNaN(a) || Number.isNaN(b)) {
    throw new Error('Fields "a" and "b" must be numbers');
  }

  // Validate operation.
  if (typeof operation !== 'string' || !Object.prototype.hasOwnProperty.call(OPERATIONS, operation)) {
    throw new Error(`Unsupported operation: ${operation}`);
  }

  if (operation === 'divide' && b === 0) {
    throw new Error('Division by zero');
  }

  const result = OPERATIONS[operation](a, b);
  return { content: [{ type: 'text', text: String(result) }] };
